var sinput, w, t, R, r;
// === Tab: mySketch ===
function setup() {
	w = max(windowWidth, windowHeight)
	createCanvas(w, w);	
	noStroke()
	background(0)
}

function draw() {
	background(0,10)

	noFill()
	translate(w/2,w/2)
	t = (frameCount/100)%100
	sinput = map(t,0,1,0,TAU)

	R = w/4.5
	for(r = R/2; r<R; r+=(Math.max(0.001, Math.abs(R/10)) || 1)){
		for(a = sinput/4; a<TAU+sinput/4; a+=(Math.max(0.001, Math.abs(TAU/11)) || 1)){
			x = r*cos(a+r) + r/4*sin(sinput+r+a) + r/4*sin(sinput+r)
			y = r*sin(a+r) + r/4*sin(sinput+r+a) + r/4*cos(sinput+r)

			fill(127.5 + 127.5*sin(sinput+r+a),
					127.5 + 127.5*cos(sinput+r+a),
					127.5 - 127.5*cos(sinput+r+a))

			//strokeWeight(w/100+w/200*sin(sinput+r+a*2))
			ellipse(x,y,w/40+w/80*sin(sinput+r+a))
		}
	}
}
